"""Exercise freshness failures without touching the real Workbench tree."""

import contextlib
import importlib.util
import io
from pathlib import Path
import subprocess
import tempfile
import unittest
from unittest.mock import patch

import yaml

SCRIPTS = Path(__file__).resolve().parent
ROOT = SCRIPTS.parents[1]
FEATURES = Path("Source/Workbench/Features")
SENTINELS = ("EventStores/EnsureEventStore.ts", "DevelopmentTools/ResetKernelState.ts")


def load(name):
    spec = importlib.util.spec_from_file_location(name.replace("-", "_"), SCRIPTS / f"{name}.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


checker = load("check-workbench-proxies")
paths = load("assert-build-affecting-paths")


def proxy(body="conflictingEvent?: string;", time="2026-10-19T10:31:26.8532100Z"):
    return ("// Copyright (c) Cratis. All rights reserved.\n\n"
            "// **DO NOT EDIT** - This file is an automatically generated file.\n"
            f"// @generated by Cratis. Source: Example.Command. Time: {time}. Hash: {'A' * 64}\n"
            f"export interface Command {{ {body} }}\n")


class Freshness(unittest.TestCase):
    def setUp(self):
        scratch = ROOT / ".ai-work" / "5046"
        scratch.mkdir(parents=True, exist_ok=True)
        self.temporary = tempfile.TemporaryDirectory(dir=scratch)
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name) / "repository"
        self.source = self.root / FEATURES
        self.output = Path(self.temporary.name) / "generated"
        self.files = {name: proxy() for name in SENTINELS}
        self.files.update({"Concurrency/Violation.ts": proxy(),
                           "Occurrences/Lifecycle.ts": proxy(),
                           "Occurrences/index.ts": "export * from './Lifecycle';\nexport * from './Manual';\n",
                           "Occurrences/Manual.ts": "// Ordinary comment\nexport const manual = 1;\n",
                           "Occurrences/Listing.tsx": "export const Listing = () => <div />;\n"})
        for name, content in self.files.items():
            self.put(self.source, name, content)
        subprocess.run(["git", "init", "--quiet", str(self.root)], check=True)
        subprocess.run(["git", "-C", str(self.root), "add", "."], check=True)

    def put(self, directory, name, content):
        target = directory / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8", newline="")

    def generate(self):
        checker.prepare(self.root, self.output)
        for name, content in self.files.items():
            if "@generated by Cratis" in content:
                self.put(self.output, name, content)

    def verdict(self):
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            result = checker.check(self.root, self.output)
        return result, output.getvalue()

    def test_equal_with_only_timestamp_and_newline_changes(self):
        self.generate()
        for name in SENTINELS:
            self.put(self.output, name, proxy(time="2026-11-01T00:00:00Z").replace("\n", "\r\n"))
        result, output = self.verdict()
        self.assertEqual(0, result, output)
        self.assertIn("4 tracked proxies", output)
        self.assertIn("4 regenerated proxies", output)
        self.assertIn("7 compared files", output)

    def test_generic_source_metadata_keeps_assembly_identity(self):
        self.generate()
        generic = "Example.OneOf`1[[Example.Command, Example, Version=1.0.0.0]]"
        for directory in (self.source, self.output):
            self.put(directory, SENTINELS[0], proxy().replace("Example.Command", generic))
        self.assertEqual(0, self.verdict()[0])
        self.put(self.output, SENTINELS[0], proxy().replace("Example.Command", generic.replace("1.0.0.0", "2.0.0.0")))
        self.assertEqual(1, self.verdict()[0])

    def test_prepare_seeds_only_handwritten_files_and_mixed_barrels(self):
        checker.prepare(self.root, self.output)
        self.assertEqual({"Occurrences/index.ts", "Occurrences/Manual.ts", "Occurrences/Listing.tsx"},
                         {p.relative_to(self.output).as_posix() for p in self.output.rglob("*") if p.is_file()})
        self.assertEqual(self.files["Occurrences/index.ts"], (self.output / "Occurrences/index.ts").read_text())

    def test_body_hash_source_and_ordinary_comments_are_compared(self):
        self.generate()
        for old, new in (("conflictingEvent?: string;", ""), ("Example.Command", "Other.Command"),
                         ("A" * 64, "B" * 64), ("Copyright", "Copywrong")):
            with self.subTest(change=old):
                self.put(self.output, SENTINELS[0], proxy().replace(old, new))
                result, output = self.verdict()
                self.assertEqual(1, result, output)
                self.assertIn(str(FEATURES / SENTINELS[0]), output)
        self.put(self.output, SENTINELS[0], proxy())
        self.put(self.output, "Occurrences/Manual.ts", self.files["Occurrences/Manual.ts"].replace("Ordinary", "Changed"))
        self.assertEqual(1, self.verdict()[0])

    def test_new_untracked_proxy_fails(self):
        self.generate()
        self.put(self.output, "New.ts", proxy())
        self.assertEqual(1, self.verdict()[0])

    def test_removed_proxy_fails(self):
        self.generate()
        (self.output / "Concurrency/Violation.ts").unlink()
        result, output = self.verdict()
        self.assertEqual(1, result, output)
        self.assertIn("missing from regeneration", output)

    def test_renamed_proxy_fails(self):
        self.generate()
        (self.output / "Concurrency/Violation.ts").rename(self.output / "Concurrency/Renamed.ts")
        result, output = self.verdict()
        self.assertEqual(1, result, output)
        self.assertIn("missing from regeneration", output)
        self.assertIn("not Git-tracked", output)

    def test_missing_lifecycle_export_and_stale_removed_export_fail(self):
        self.generate()
        for content in ("export * from './Manual';\n",
                        self.files["Occurrences/index.ts"] + "export * from './Removed';\n"):
            with self.subTest(content=content):
                self.put(self.output, "Occurrences/index.ts", content)
                result, output = self.verdict()
                self.assertEqual(1, result, output)
                self.assertIn("Occurrences/index.ts", output)

    def test_missing_empty_noop_and_non_debug_generation_fail(self):
        with self.assertRaises(ValueError):
            checker.check(self.root, self.output)
        self.output.mkdir()
        with self.assertRaises(ValueError):
            checker.check(self.root, self.output)
        self.output.rmdir()
        checker.prepare(self.root, self.output)
        with self.assertRaises(ValueError):
            checker.check(self.root, self.output)
        self.put(self.output, SENTINELS[0], proxy())
        with self.assertRaisesRegex(ValueError, "ResetKernelState"):
            checker.check(self.root, self.output)

    def test_malformed_or_misplaced_metadata_fails(self):
        for content in (proxy().replace("Time: 2026", "Time: invalid2026"),
                        proxy().replace(". Hash:", ". Broken:"),
                        "export const first = 1;\n" + proxy()):
            with self.subTest(content=content):
                self.put(self.source, SENTINELS[0], content)
                with self.assertRaises(ValueError):
                    checker.prepare(self.root, self.output)

    def test_unsafe_destination_and_symlinks_fail(self):
        for target in (self.source, self.source / "nested", self.source.parent):
            with self.subTest(target=target), self.assertRaises(ValueError):
                checker.prepare(self.root, target)
        self.output.mkdir()
        with self.assertRaises(ValueError):
            checker.prepare(self.root, self.output)
        (self.source / SENTINELS[0]).unlink()
        (self.source / SENTINELS[0]).symlink_to(self.source / SENTINELS[1])
        with self.assertRaises(ValueError):
            checker.prepare(self.root, self.output / "fresh")

    def test_empty_missing_and_untracked_source_fail(self):
        with patch.object(checker, "tracked_paths", return_value=[]), self.assertRaises(ValueError):
            checker.prepare(self.root, self.output)
        (self.source / SENTINELS[0]).unlink()
        with self.assertRaises(ValueError):
            checker.prepare(self.root, self.output)
        self.put(self.source, SENTINELS[0], proxy())
        self.put(self.source, "Untracked.ts", proxy())
        with self.assertRaisesRegex(ValueError, "Untracked.ts"):
            checker.prepare(self.root, self.output)

    def test_output_outside_features_is_irrelevant(self):
        self.generate()
        self.put(self.root, "unrelated.ts", proxy())
        self.assertEqual(0, self.verdict()[0])


class WorkflowContract(unittest.TestCase):
    def test_ordinary_pr_runs_fixture_prepare_debug_check_before_release(self):
        workflow = yaml.load((ROOT / ".github/workflows/dotnet-build.yml").read_text(), Loader=yaml.BaseLoader)
        job = workflow["jobs"]["dotnet-build"]
        self.assertEqual("needs.already-ran.outputs.skip != 'true'", job["if"])
        steps = job["steps"]
        destination = next(step for step in steps if "WORKBENCH_PROXIES=$RUNNER_TEMP/workbench-proxies" in step.get("run", ""))
        self.assertIn('>> "$GITHUB_ENV"', destination["run"])
        self.assertNotIn("if", destination)
        self.assertNotIn("continue-on-error", destination)
        fragments = ("test-check-workbench-proxies.py", "WORKBENCH_PROXIES=$RUNNER_TEMP/workbench-proxies",
                     "check-workbench-proxies.py prepare",
                     "dotnet build Source/Kernel/Core/Core.csproj", "check-workbench-proxies.py check",
                     "dotnet build --configuration Release")
        selected = [next((i, step) for i, step in enumerate(steps) if fragment in step.get("run", ""))
                    for fragment in fragments]
        self.assertEqual(sorted(i for i, _ in selected), [i for i, _ in selected])
        for _, step in selected:
            self.assertNotIn("if", step)
            self.assertNotIn("continue-on-error", step)
        generation = selected[3][1]["run"]
        for flag in ("--configuration Debug", "-p:DisableProxyGenerator=false", "-p:CratisProxiesIncremental=false",
                     "-p:DisableGrpcContractGeneration=true", "-p:DisableProtoGeneration=true",
                     "-p:DisableDockerBuild=true", '-p:CratisProxiesOutputPath=$WORKBENCH_PROXIES'):
            self.assertIn(flag, generation)
        self.assertNotIn("--no-build", generation)
        self.assertNotIn("-p:OutputPath=", generation)
        self.assertIn("-p:DisableProxyGenerator=true", selected[5][1]["run"])

    def test_build_affecting_paths_cover_proxy_inputs_and_gate(self):
        workflow = yaml.load((ROOT / ".github/workflows/dotnet-build.yml").read_text(), Loader=yaml.BaseLoader)
        filters = workflow["on"]["pull_request"]["paths"]
        for required in ("Source/**", ".github/scripts/**", ".github/workflows/**",
                         "Directory.Packages.props", "Directory.Build.props", "Directory.Build.targets", "global.json"):
            self.assertEqual([], paths.uncovered(required, filters), required)


if __name__ == "__main__":
    unittest.main()
